const fs = require('fs');
const {execSync} = require('child_process');
try {
  const status = execSync('git status --short 2>/dev/null').toString().trim();
  const log = execSync('git log --oneline -3 2>/dev/null').toString().trim();
  const date = new Date().toISOString().split('T')[0];
  const note = [
    '',
    '## Session Checkpoint — ' + date,
    'Last 3 commits:',
    log || '(none)',
    '',
    'Uncommitted changes at session end:',
    status || '(clean)',
  ].join('\n');
  const current = fs.readFileSync('CLAUDE.md', 'utf8');
  if (!current.includes('Session Checkpoint — ' + date)) {
    fs.writeFileSync('CLAUDE.md', current + note + '\n');
  }
} catch(e) {}
